import { HonoRequest } from '../clone/src/request'
async function test(contentType: 'multipart'|'urlencoded') {
  let req: Request
  if (contentType === 'multipart') { const f = new FormData(); f.append('x','value'); req = new Request('http://localhost/',{method:'POST',body:f}) }
  else { req = new Request('http://localhost/',{method:'POST',body:new URLSearchParams({x:'value'})}) }
  const honoReq = new HonoRequest(req)
  console.log(contentType, 'formData first', [...(await honoReq.formData()).entries()])
  try { console.log(contentType, 'parseBody next', await honoReq.parseBody()) } catch(e) { console.log(contentType, 'parseBody error', e) }
}
await test('multipart'); await test('urlencoded')
EOF
